/* GIUT map panel — warm card direction from the approved reference. */
body .explore-panel{
  width:430px;
  max-width:calc(100% - 48px);
  background:#fff;
  border:1px solid #eadfda;
  border-radius:30px;
  box-shadow:0 18px 48px rgba(67,36,28,.16);
  overflow:hidden;
}
body .explore-start,
body .show-welcome .explore-start{
  position:relative;
  min-height:232px;
  padding:31px 32px 28px;
  background:#fff6e8;
  border:0;
  color:#4c281f;
}
body .explore-start .eyebrow{
  display:block;
  color:#9c704f;
  font-size:12px;
  font-weight:800;
  letter-spacing:.13em;
}
body .explore-start h1{
  max-width:260px;
  margin:18px 0 12px;
  color:#4c281f;
  font-size:36px;
  font-weight:900;
  line-height:1.15;
  letter-spacing:-.06em;
}
body .explore-start>p:not(.eyebrow){
  max-width:260px;
  color:#9a7764;
  font-size:15px;
  line-height:1.75;
}
body .explore-start .welcome-cat{
  display:block;
  position:absolute;
  top:78px;
  right:26px;
  width:94px;
  height:108px;
  opacity:1;
}
body .explore-start>.primary-button{
  width:100%;
  min-height:58px;
  margin-top:24px;
  border:0;
  border-radius:18px;
  background:#ffb633;
  color:#4c281f;
  font-size:16px;
  font-weight:850;
  box-shadow:none;
}
body .panel-content{background:#fff;}
body .explore-panel .list-heading{
  min-height:66px;
  padding:18px 28px 14px;
  background:#fff;
}
body .explore-panel .list-heading>span{color:#4c281f;font-size:18px;font-weight:850;}
body .explore-panel .list-heading b{color:#b66f2b;font-size:15px;}
body .explore-panel .spot-list{padding:0 22px 24px;background:#fff;}
body .explore-panel .spot-card,
body .explore-panel .spot-card.featured{
  border:1px solid #dda66f;
  border-radius:26px;
  background:#fff;
  box-shadow:none;
}
body .explore-panel .spot-photo{border-radius:25px 25px 0 0;}
body .explore-panel .ar-label{background:#ffb633;color:#4c281f;}
body .explore-panel .example-label{background:#fffaf2;color:#9a6a47;}
body .explore-panel .category-label{color:#b66f2b;}
body .explore-panel .card-title{color:#4c281f;}
body .explore-panel .panel-footer{background:#fff;border-color:#eee1d8;color:#9a7764;}
body .explore-panel .panel-footer button{color:#4c281f;}

/* Collection banner character and tidy spot counter. */
body .scrapbook-heading{
  position:relative;
  min-height:220px;
  overflow:visible;
  padding-right:min(43vw,500px);
}
body .scrapbook-heading .scrapbook-hanging-cat{
  position:absolute;
  z-index:2;
  right:3%;
  bottom:-68px;
  width:min(43vw,470px);
  height:auto;
  pointer-events:none;
  object-fit:contain;
}
body .explore-panel .list-heading b{
  margin-left:4px;
  padding:0;
  border-radius:0;
  background:transparent;
  color:inherit;
  font-size:inherit;
  font-weight:inherit;
}

@media(max-width:760px){
  body .explore-panel,
  body .show-welcome .explore-panel{
    left:14px;
    right:14px;
    width:auto;
    max-width:none;
    border-radius:27px;
    background:#fff;
    box-shadow:0 14px 42px rgba(67,36,28,.18);
  }
  body .panel-swipe-zone{background:#fff6e8;}
  body .explore-start,
  body .show-welcome .explore-start{
    min-height:210px;
    padding:5px 22px 22px;
    background:#fff6e8;
  }
  body .explore-start .eyebrow{display:block;font-size:10px;}
  body .explore-start h1{max-width:220px;margin:10px 0 8px;font-size:29px;}
  body .explore-start>p:not(.eyebrow){display:block;max-width:230px;font-size:13px;line-height:1.65;}
  body .explore-start .welcome-cat{display:block;top:39px;right:18px;width:76px;height:89px;}
  body .explore-start>.primary-button{min-height:52px;margin-top:17px;border-radius:16px;font-size:14px;}
  body .panel-content{background:#fff;}
  body .explore-panel .list-heading{min-height:54px;padding:13px 20px 10px;}
  body .explore-panel .list-heading>span{font-size:16px;}
  body .explore-panel .spot-list{padding:0 14px 18px;}
  body .scrapbook-heading{min-height:170px;padding-right:43%;}
  body .scrapbook-heading .scrapbook-hanging-cat{right:-3%;bottom:-39px;width:49%;}
}
